import pytest
from duration import parse_duration


@pytest.mark.parametrize("text,secs", [("45s", 45), ("90m", 5400), ("1h30m", 5400),
                                       ("2d", 172800), ("1h 5m 10s", 3910),
                                       ("1D2H", 93600), ("0s", 0)])
def test_validos(text, secs):
    assert parse_duration(text) == secs


@pytest.mark.parametrize("bad", ["", "10", "5x", "1m1h", "1h1h", "h", "-5m", "1.5h"])
def test_invalidos(bad):
    with pytest.raises(ValueError):
        parse_duration(bad)

